import{_ as i,C as r,o,c,a2 as a,j as t,G as s}from"./chunks/framework.BgSoyxN5.js";const T=JSON.parse('{"title":"Рыночный стресс: давление растёт или уходит? | TickerForge","description":"Волатильность, кредит и ставки как один композит с направлением, каждый день — вместо трёх отдельных заголовков в три разных дня. На что отвечает и как публиковать это в своём канале.","frontmatter":{"title":"Рыночный стресс: давление растёт или уходит? | TickerForge","description":"Волатильность, кредит и ставки как один композит с направлением, каждый день — вместо трёх отдельных заголовков в три разных дня. На что отвечает и как публиковать это в своём канале.","aside":false,"locale":"ru","alternateLocales":{"en":"/market-intelligence/market-stress","ru":"/ru/market-intelligence/market-stress"},"pageClass":"partners-page"},"headers":[],"relativePath":"ru/market-intelligence/market-stress.md","filePath":"ru/market-intelligence/market-stress.md","lastUpdated":1788410450000}'),h={name:"ru/market-intelligence/market-stress.md"},d={class:"partners-wide"},m={class:"partners-post-gallery"};function p(g,e,_,k,u,f){const l=r("PartnerPostImage"),n=r("PartnerChannelCta");return o(),c("div",null,[e[0]||(e[0]=a('<h1 id="рыночныи-стресс" tabindex="-1">Рыночный стресс <a class="header-anchor" href="#рыночныи-стресс" aria-label="Permalink to &quot;Рыночный стресс&quot;">​</a></h1><p>Волатильность, кредит и ставки говорят одно и то же чаще, чем принято замечать. Это чтение говорит это одним числом, с направлением, каждый день.</p><div class="partners-hero-actions"><a class="partners-button partners-button--primary" href="https://t.me/TickerForgeBot?start=src_channel_market_stress" rel="nofollow">Открыть карточку рыночного стресса</a><a class="partners-button partners-button--secondary" href="#publish">Публиковать в своём канале</a></div><p class="partners-locale-switch"><a href="/market-intelligence/market-stress" hreflang="en">Read this page in English</a></p><p class="partners-backlink"><a href="/ru/market-intelligence/">Все чтения Market Intelligence</a> · <a href="/ru/market-intelligence/market-regime">Рыночный режим</a> · <a href="/ru/market-intelligence/fear-and-greed">Fear &amp; Greed</a></p><h2 id="answers" tabindex="-1">На какой вопрос отвечает <a class="header-anchor" href="#answers" aria-label="Permalink to &quot;На какой вопрос отвечает {#answers}&quot;">​</a></h2><p><strong>«Давление на рынок нарастает или спадает?»</strong></p><p>Все входные данные публичны и бесплатны. Никто не собирает читателю их общее направление. Лента пишет про VIX в день, когда двинулся VIX, про кредитные спреды — когда вышла кредитная история, и про кривую доходности — когда кто-то пишет про рецессию. Три разных дня, три разные темы, общего ответа нет.</p><h2 id="why" tabindex="-1">Почему композит сильнее трёх заголовков <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Почему композит сильнее трёх заголовков {#why}&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Одно число, каждый день, посчитанное одинаково.</strong> Сравнимо со вчера и с прошлым месяцем — именно это и делает число пригодным для наблюдения.</li><li><strong>Направление и есть сообщение.</strong> Стресс 42 и падает — это другой рынок, чем стресс 42 и растёт. Пост говорит, что именно.</li><li><strong>Стресс идёт впереди метки.</strong> Растущий стресс обычно предшествует понижению <a href="/ru/market-intelligence/market-regime">режима</a>: это то чтение, которое заранее говорит читателю ждать движения большой метки.</li><li><strong>У смены режима стресса свой алерт.</strong> Когда сам режим стресса поворачивает, это публикуется отдельным событием, а не прячется внутри дневного числа.</li><li><strong>Правило открыто.</strong> <a href="/methodology/market-stress-index">Методология</a> называет входы и веса, так что с конструкцией можно не согласиться предметно.</li></ul></div><h2 id="example" tabindex="-1">Как выглядит пост <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Как выглядит пост {#example}&quot;">​</a></h2>',11)),t("div",d,[t("div",m,[s(l,{src:"/partners/examples/daily-market-stress-sample.png",alt:"Пост TickerForge «Рыночный стресс»: композитный индекс и шкала направления — давление ослабевает, смешанное или растёт",caption:"Композит, его направление и что его сдвинуло.","zoom-label":"Открыть пример поста в полном размере","close-label":"Закрыть","enlarge-label":"Нажмите, чтобы открыть в полном размере","shrink-label":"Нажмите, чтобы вписать в экран"})])]),e[1]||(e[1]=a('<h2 id="method" tabindex="-1">Как это считается <a class="header-anchor" href="#method" aria-label="Permalink to &quot;Как это считается {#method}&quot;">​</a></h2><p>Композит по волатильности, высокодоходному кредиту, длинным ставкам и кривой доходности, нормализованный так, чтобы число означало одно и то же во времени, а не только относительно последних сессий.</p><p>Полное описание: <a href="/methodology/market-stress-index">Market Stress Index methodology</a>.</p><h2 id="publish" tabindex="-1">Два способа этим пользоваться <a class="header-anchor" href="#publish" aria-label="Permalink to &quot;Два способа этим пользоваться {#publish}&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Читать.</strong> Ежедневный пост выходит в публичном канале TickerForge; карточка с текущим индексом и направлением — в боте.</li><li><strong>Публиковать.</strong> Рыночный стресс доступен для партнёрских пилотов — напишите об этом на странице <a href="/ru/partners/market-news">рыночных новостей</a>: мы приоритизируем по тому, что партнёры реально просят.</li></ul></div>',5)),s(n),e[2]||(e[2]=a('<p>Стресс — это контекст, а не сигнал. Высокое значение не указание продавать, низкое не разрешение добирать риск. TickerForge — образовательное ПО для поддержки решений, не инвестиционная рекомендация.</p><h2 id="смежные-страницы" tabindex="-1">Смежные страницы <a class="header-anchor" href="#смежные-страницы" aria-label="Permalink to &quot;Смежные страницы&quot;">​</a></h2><ul><li><a href="/ru/market-intelligence/">Все чтения Market Intelligence</a></li><li><a href="/methodology/market-stress-index">Методология Market Stress Index</a></li><li><a href="/ru/market-intelligence/market-regime">Рыночный режим</a></li><li><a href="/ru/partners/market-news">Партнёрская программа по рыночным новостям</a></li></ul>',3))])}const P=i(h,[["render",p]]);export{T as __pageData,P as default};
